"use strict";
const absFloor = require("./absFloor-CImRXpov.js");
const monthDiff = require("./monthDiff-DFAMKa42.js");
const parse = require("./parse.js");
function diffInYears(date, input, asFloat) {
  const parsed = parse(input);
  const output = monthDiff.monthDiff(date, parsed) / 12;
  return asFloat ? output : absFloor.absFloor(output);
}
module.exports = diffInYears;
